use vstd::prelude::*;

/*
We use Verus to verify that given:
  - N > 0,
  - a.len() == N,
  - sum.len() == 1,
after execution, every element of `a` is equal to N.
The auxiliary array `sum` is unconstrained in the post‐state.
*/

verus! {

    #[verifier(publish)]
    pub fn myfun(a: &mut Vec<i32>, sum: &mut Vec<i32>, N: i32)
        requires
            // Preconditions
            N > 0,
            a.len() == N as usize,
            sum.len() == 1,
        ensures
            // Postcondition: every index k in [0, a.len()) stores N
            forall |k: usize| k < a.len() ==> a[k] == N
    {
        // Cache the length
        let len: usize = a.len();

        // We'll walk i from 0 up to len.
        let mut i: usize = 0;
        while i < len {
            // Loop invariants:
            //   1) 0 <= i <= len
            //   2) For all j < i, a[j] == N
            invariant i <= len;
            invariant forall |j: usize| j < i ==> a[j] == N;
            decreases len - i;

            // Body: set a[i] = N and advance i
            a[i] = N;
            i += 1;
        }

        // At loop exit, i == len, so by the invariant,
        // ∀ j < len, a[j] == N, which is exactly our postcondition.
    }

}